import argparse,subprocess,pathlib,json,time
p=argparse.ArgumentParser();p.add_argument('--name',default='compact-single');p.add_argument('--gpus',default='1');p.add_argument('--tp',default='1');p.add_argument('--util',default='.40');p.add_argument('--port',default='8741');p.add_argument('--graphs',action='store_true');a=p.parse_args();root=pathlib.Path(__file__).resolve().parents[1]
cmd=['systemd-run','--user','--unit=h2ol-'+a.name,'--collect','-p',('MemoryHigh=8G' if a.tp=='2' else 'MemoryHigh=6500M'),'-p',('MemoryMax=9G' if a.tp=='2' else 'MemoryMax=7G'),'-p','MemorySwapMax=0','-p','CPUQuota=250%','-p','Nice=10','-p','IOWeight=20','-p','TasksMax=256','-p','TimeoutStopSec=10','-p','WorkingDirectory='+str(root),'-p','StandardOutput=append:'+str(root/'evidence'/f'{a.name}-engine.log'),'-p','StandardError=inherit','--setenv=CUDA_VISIBLE_DEVICES='+a.gpus,str(root/'.venv/bin/python'),str(root/'scripts/compact_server.py'),'--tp',a.tp,'--util',a.util,'--port',a.port]+(['--graphs'] if a.graphs else [])
d={'started':time.time(),'command':cmd,'unit':'h2ol-'+a.name};subprocess.run(cmd,check=True);(root/'evidence'/f'{a.name}-startup.json').write_text(json.dumps(d,indent=2))
